function invalidateMapArt(mapId,layer=null,area=null){mapPreviews.delete(mapId);for(const [key,c]of tileChunks)if(c.mapId===mapId&&(!layer||c.layer===layer)&&(!area||c.cx*16<=area.x1&&(c.cx+1)*16>area.x0&&c.cy*16<=area.y1&&(c.cy+1)*16>area.y0))tileChunks.delete(key);}
