async function ensureImage(id) {
  if(imageCache.has(id))return imageCache.get(id);
  if(imagePending.has(id))return imagePending.get(id);
  if(badImages.has(id))return null;
  const a=asset(id);if(!a)return null;
  const generation=imageGeneration;const promise=new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{if(generation!==imageGeneration){resolve(img);return;}imagePending.delete(id);if(img.width!==a.width||img.height!==a.height||img.width*img.height>32e6){badImages.add(id);reject(new Error(`The dimensions of ${a.name} do not match its project data.`));return;}if(generation===imageGeneration){imageCache.set(id,img);imageLoaded(id);}resolve(img);};img.onerror=()=>{if(generation!==imageGeneration){resolve(null);return;}imagePending.delete(id);badImages.add(id);reject(new Error(`Could not open image: ${a.name}`));};img.src=a.data||a.src;});
  imagePending.set(id,promise);return promise;
}
function imageNow(id){const im=imageCache.get(id);if(!im){previewMissing?.add(id);if(!imagePending.has(id)&&!badImages.has(id))ensureImage(id).catch(showError);}return im;}
async function loadMapImages(map){if(map===m()&&view==='map')protectMapImages();const images=[];for(const id of mapImages(map))images.push(ensureImage(id));await Promise.all(images);if((map.nativeAssemblies||[]).some(a=>a.templateId==='included-native-bookcase-v2'&&a.reconstruction&&!a.reconstruction.floorRepairRevision&&!a.reconstruction.floorRepairNeedsReview)){const im=await ensureImage(map.rom.atlasId),library=await readSettlementLibrary();if(im){const cv=document.createElement('canvas');cv.width=im.width;cv.height=im.height;const ctx=cv.getContext('2d');ctx.drawImage(im,0,0);const result=upgradeReviewedFloorPatches(project,map,{width:cv.width,height:cv.height,pixels:ctx.getImageData(0,0,cv.width,cv.height).data},library.templates);releaseCanvas(cv);if(result.changed){markDirty();toast('Repaired '+result.changed+' floor tiles from the earlier bookcase patch.');}if(result.skipped)toast('An earlier floor patch has further edits. It needs manual review.');}}}
