  strokeBefore=captureEdit(project,m().id);g.kind=activeTool;g.localArt=['brush','erase','terrain','texture','rules','rulesRect'].includes(activeTool);if(!g.localArt)invalidateMapArt(m().id);
  if(activeTool==='ledge')fieldTools.paintLedge(t.x,t.y);if(activeTool==='tree')builder.paintTrees(t.x,t.y);if(activeTool==='wall')world.paint(t.x,t.y);if(activeTool==='rules')world.rule(t.x,t.y);
