async function checkEmbeddedImages(next){
  for(const a of next.assets)if(a.data)await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{if(img.width!==a.width||img.height!==a.height||img.width*img.height>32e6)reject(new Error(`The image dimensions for ${a.name} do not match the project.`));else resolve();};img.onerror=()=>reject(new Error(`The image ${a.name} cannot be decoded.`));img.src=a.data;});
}
