async function saveBlob(blob,filename,share=false){
  if(window.NativeBridge?.exportBlob){await window.NativeBridge.exportBlob(blob,filename,share);return;}
  if(window.NativeBridge?.saveFile){const data=await asDataURL(blob);if(share&&window.NativeBridge.shareFile)window.NativeBridge.shareFile(filename,data.split(',')[1],blob.type);else window.NativeBridge.saveFile(filename,data.split(',')[1],blob.type);toast(share?'Opening share options…':'Saving file…');return;}
  if(share){const file=new File([blob],filename,{type:blob.type});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:project.name});}catch(e){if(e.name!=='AbortError')throw e;}return;}toast('Sharing files is unavailable here. Use Save file and attach it manually.');return;}
  const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('File downloaded. Keep it as a backup or attach it here.');
}
