function activateTool(t){
  setView('map');if(t==='brushes'){toolbox.defaultBrush();return;}
  if(t==='link'){setTool('link');return;}if(t==='crop'){mapCrop.begin();return;}
  if(t==='field'){fieldTools.open();return;}if(t==='play'){world.startPlay();return;}
  if(t==='building'){toolbox.state.scope='buildings';setTool('stamp');return;}
  if(t==='portal'){mapLinks.begin();return;}if(t==='gate'){world.open('gates');return;}
  if(t==='tree'&&!builder.state.treeIds.length)builder.state.treeIds=[builder.trees()[0]?.id].filter(Boolean);
  setTool(t);if(['wall','wallbox','rules'].includes(t))activeLayer='details';
}
