  if(sig!==toolSignature){toolSignature=sig;$('#tools').innerHTML=core.map(id=>{const[svg,label,hint]=id==='brushes'?['brush','Brushes','Paths, textures, trees, walls and rooms']:toolInfo[id];return `<button data-tool="${id}" title="${hint}" aria-label="${label}: ${hint}">${icon(svg)}<span>${label}</span></button>`;}).join('')+`<button id="moreMapTools" title="More map tools" aria-label="More map tools">${icon('menu')}<span>More</span></button>`;}
  $$('#tools [data-tool]').forEach(b=>{const active=b.dataset.tool===selected;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
