function sourceWordForRender(map,x,y){return(sourceBlock(map,x,y)||0)&1023;}
async function exportRomDialog(){
 if(romSession){const restored=await resolveROMExportSource(project,romSession.reader.bytes);if(restored){const reader=await new GbaMaps(restored.source,romSession.reader.filename).discover();identifyEngineProfile(reader.bytes,restored.sourceId);romSession={reader,id:restored.sourceId};}}
 if(!romSession){modal('Open the source ROM','<p>Choose the original GBA ROM used by this project. The editor will compile an edited copy with your map art, movement rules, portals and interactions.</p><button id="chooseExportROM" type="button" class="primary">Choose original ROM</button>');$('#chooseExportROM').onclick=()=>{romPurpose='export';pickROM();};return;}
 if(auditProjectLayers(project).length){reviewJSONLayers(exportRomDialog);return;}
 const exitConflicts=auditNativeExits(project,romSession.reader,romSession.id);if(exitConflicts.length){nativeExitReview({project:()=>project,modal,esc,$,open:async p=>{p.id=uid();await switchProject(p);await persist();}},exitConflicts,exportRomDialog);return;}
 if(project.romRefresh?.status==='blocked'){await reviewROMRefresh(romSession.reader,romSession.id,null);return;}
 const linkedSource=project.maps.find(m=>m.rom?.sourceId)?.rom.sourceId;if(linkedSource&&linkedSource!==romSession.id&&!project.maps.some(m=>m.rom?.sourceId===romSession.id)){modal('Review the project’s ROM revision','<p>This project belongs to another ROM revision. Refresh a separate project copy first so its artwork, movement and exit settings are retained.</p><button id="refreshExportSource" type="button" class="primary">Review refresh against opened ROM</button>');$('#refreshExportSource').onclick=()=>reviewROMRefresh(romSession.reader,romSession.id,null).catch(showError);return;}const maps=project.maps.filter(a=>a.rom&&!a.rom.isCopy&&(a.rom.sourceId===romSession.id||a.rom.generated&&!a.rom.sourceId));const gameChanges=await gameEditCount()+(Object.keys(project.textEdits?.[romSession?.id]||{}).length+(project.regionMaps?.[romSession?.id]?1:0)+(project.travelEdits?.[romSession?.id]?1:0));if(!maps.length&&!gameChanges){modal('Bind a map to your ROM','<p>This project has no map slots linked to the opened ROM. Import its maps, or bind your current design to an existing ROM map slot.</p><button id="bindCurrentMap" type="button">Choose ROM map slot</button>');$('#bindCurrentMap').onclick=bindRomMapDialog;return;}
 modal('Export an edited GBA ROM',`<p>${maps.length} linked map${maps.length===1?'':'s'} and ${gameChanges} game/sprite edits will be checked against <b>${esc(romSession.reader.filename)}</b>. The complete ROM is copied first; linked project maps are then applied. Unrelated source content is retained.</p>${project.maps.length!==maps.length?'<label class="check"><input id="allowUnboundMaps" type="checkbox"> Export only the '+maps.length+' linked maps; keep '+(project.maps.length-maps.length)+' unbound/copy maps in JSON only</label>':''}<label class="check"><input id="staticRomArt" type="checkbox" ${maps.some(m=>m.rom?.recoveryRequiresStatic||m.region||m.generator?.version===3)?'checked':''}> Use static tiles on edited maps to free graphics space</label><p class="hint-line">Recommended for generated settlements. Turn this off to preserve source tile animation. If new artwork needs more space, static mode packs both tile banks and freezes their animation on the edited maps. GBA palettes may change some imported colours; the next screen previews the actual exported art.</p><label class="check"><input id="convertRomPalettes" type="checkbox"> Prepare shared native palettes (review any colour changes before saving)</label><p class="hint-line">Keeps original project artwork, layer masks and collision. The output preview shows the GBA palette conversion. Requires static artwork.</p><p>Buildings, linked interiors, walls, walking and jump rules, HM objects, Flash, portals, events and opening gates are compiled. Planning notes and reference images stay in the project.</p><p id="romCompileProgress" class="hint-line"></p>`,async()=>{const staticArtwork=$('#staticRomArt').checked,progress=s=>{if($('#romCompileProgress'))$('#romCompileProgress').textContent=s;};busy(true,'Compiling ROM…');try{await persist();const convert=$('#convertRomPalettes').checked;if(convert&&!staticArtwork)throw Error('Enable static artwork to prepare shared palettes.');let compiledProject=convert?await prepareNativeArtwork(project,romSession.reader,romSession.id,renderForRom,{allowColorChanges:true,nativeMiniatures:originalArtworkMiniatures,progress}):project;const build=()=>buildRom(compiledProject,romSession.reader,{sourceId:romSession.id,renderMap:renderForRom,rasterTimeline:renderNativeOpening,wallStyles:world.walls(),staticArtwork,allowUnboundMaps:!!$('#allowUnboundMaps')?.checked,gateRedrawSpecial:discoverGateRedraw(romSession.reader,{sourceSha256:romSession.id})?.index??null,progress});let result;try{result=await build();}catch(error){if(!error.nativePackStale||convert||!staticArtwork)throw error;progress('Updating native artwork for the edited maps…');compiledProject=await prepareNativeArtwork(project,romSession.reader,romSession.id,renderForRom,{allowColorChanges:true,nativeMiniatures:originalArtworkMiniatures,progress});result=await build();}progress('Preserving the source for your next edit…');await rememberROMExport(result);progress('Checking exported map data…');const check=await new GbaMaps(result.bytes,'Export validation').discover();for(const report of result.reports){const map=check.byKey(report.key);if(!map)throw Error('The exported map table did not reopen correctly.');}showRomReview(result,check);return false;}finally{busy(false);}},'Compile & review');
}
function showRomReview(result,reader){const changed=result.reports.filter(r=>r.changed),report=changed.find(r=>r.mapId===m().id)||changed[0]||result.reports[0],filename=safeName(romSession.reader.filename.replace(/\.gba$/i,''))+'_Studio_v4.66.0.gba';modal('Review your playable ROM',`<p><b>${changed.length} maps changed · ${result.dataReports?.length||0} game/sprite records</b> · ${(result.bytes.length/1048576).toFixed(1)} MB GBA copy.</p>${result.reports.length?`<label>Preview map<select id="romReviewMap">${result.reports.map(r=>`<option value="${esc(r.key)}" ${r.key===report.key?'selected':''}>${esc(r.name)}${r.changed?' · edited':''}</option>`).join('')}</select></label><div class="rom-preview-wrap"><canvas id="romReviewPreview" aria-label="Actual compiled GBA artwork"></canvas></div>`:''}${result.dataReports?.length?`<details><summary>Game data written to this ROM</summary><p>${result.dataReports.map(esc).join('<br>')}</p></details>`:''}${result.warnings.map(s=>`<p class="hint-line">${esc(s)}</p>`).join('')}${changed.some(r=>r.staticArtwork)?'<p class="callout">Tile animation is static on maps sharing the exported tilesets.</p>':''}<p>Play this copy to check the actual game. Save editable .gba preserves your project, hidden ground and source data in unused ROM space. Reopening it restores editable objects automatically. If space is insufficient, save the ROM + project archive. Plain .gba export contains only the playable result.</p><div class="button-row"><button id="saveEditableRom" type="button" class="primary">Save editable .gba</button><button id="saveRomProject" type="button">Save ROM + editable project (.zip)</button><button id="saveRomSidecar" type="button">Save matching editable project (.json)</button><button id="saveCompiledRom" type="button">Save .gba only</button><button id="shareCompiledRom" type="button">Share .gba</button><button id="playCompiledRom" type="button">Play in app</button><button id="saveCompiledPatch" type="button">Create BPS patch</button></div>`);if($('#romReviewMap')){const preview=()=>{const data=reader.render(reader.byKey($('#romReviewMap').value)),c=$('#romReviewPreview');c.width=data.width;c.height=data.height;c.getContext('2d').drawImage(rgbaCanvas(data),0,0);};$('#romReviewMap').onchange=preview;preview();}const blob=new Blob([result.bytes],{type:'application/octet-stream'});$('#saveEditableRom').onclick=async()=>{busy(true,'Preserving editable ROM…');try{const data=await embedROMProject(result.bytes,romSession.reader.bytes,await portableProject());await saveBlob(new Blob([data],{type:'application/octet-stream'}),filename);}catch(e){showError(e);}finally{busy(false);}};let savingArchive=false;$('#saveRomProject').onclick=async()=>{if(savingArchive)return;savingArchive=true;const error=$('#dialogError');if(error){error.textContent='';error.hidden=true;}const buttons=[...$('#dialog').querySelectorAll('button')],states=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);busy(true,'Preparing ROM + project archive…');const status=document.createElement('p');status.className='callout';status.setAttribute('role','status');$('#saveRomProject').parentElement.after(status);const progress=text=>{status.textContent=text;};try{progress('Preparing editable project…');await new Promise(r=>setTimeout(r,0));const p=await portableProject(),pack=await makeROMArchive(result.bytes,romSession.reader.bytes,p,filename,{progress});progress(`Saving compressed archive (${(pack.size/1048576).toFixed(1)} MB)…`);await saveBlob(pack,filename.replace(/\.gba$/, '_editable.zip'));progress('Archive prepared and sent to the file saver. Watch for the saved-file confirmation.');}catch(e){progress('Archive was not saved: '+e.message);showError(e);}finally{savingArchive=false;buttons.forEach((b,i)=>b.disabled=states[i]);busy(false);}};$('#saveRomSidecar').onclick=async()=>{busy(true,'Preserving editable project…');try{const sidecar=await createROMProjectSidecar(result.bytes,romSession.reader.bytes,await portableProject(),{sourceId:romSession.id,reports:result.reports});await saveBlob(new Blob([JSON.stringify(sidecar)],{type:'application/json'}),filename.replace(/\.gba$/,'.pokebacon.json'));}catch(e){showError(e);}finally{busy(false);}};$('#saveCompiledRom').onclick=()=>saveBlob(blob,filename).catch(showError);$('#shareCompiledRom').onclick=()=>saveBlob(blob,filename,true).catch(showError);$('#playCompiledRom').onclick=()=>launchCompiledPlay(result).catch(showError);$('#saveCompiledPatch').onclick=()=>{try{const patch=makeBPS(romSession.reader.bytes,result.bytes,'PokéBacon Studio 4.66.0 · '+project.name),checked=applyBPS(romSession.reader.bytes,patch);if(checked.bytes.length!==result.bytes.length||checked.bytes.some((b,i)=>b!==result.bytes[i]))throw Error('The BPS patch did not reproduce this exact compiled ROM.');saveBlob(new Blob([patch],{type:'application/octet-stream'}),filename.replace(/\.gba$/,'.bps')).catch(showError);}catch(e){showError(e);}};}

function bindRomMapDialog(){if(!romSession){romPurpose='export';pickROM();return;}modal('Choose the ROM map to replace',`<p>Your current design will replace the artwork/layout in this ROM map slot when you export. Source events are retained unless you explicitly replace their dialogue. The review screen checks the result before saving.</p><label>Map slot<select id="bindRomKey">${romSession.reader.maps.map(n=>`<option value="${esc(n.key)}">${esc(n.label)} · ${n.key} · ${n.layout.width} × ${n.layout.height}</option>`).join('')}</select></label>`,()=>{const n=romSession.reader.byKey($('#bindRomKey').value);change(()=>{m().rom={sourceId:romSession.id,key:n.key,bank:n.bank,index:n.index,label:n.label,headerAddress:n.address,layoutAddress:n.layout.address,blocksAddress:n.layout.blocks,originalWidth:n.layout.width,originalHeight:n.layout.height,originalBlocks:Array.from(romSession.reader.blocks(n)),attributes:romSession.reader.atlas(n).attrs,events:romSession.reader.events(n),connections:romSession.reader.connections(n),connectedEvents:[]};project.romSources??=[];if(!project.romSources.some(s=>s.id===romSession.id))project.romSources.push({id:romSession.id,...romSession.reader.summary()});});toast('Map slot assigned. Use Export → Edited GBA ROM.');},'Use this ROM map slot');}

