function workspaceMenu(){
  modal('Workspaces',`<p class="hint-line">Choose an editor.</p><div class="workspace-choices">${[['map','Map editor','Tiles, objects, interiors, brushes, events and map connections','maps'],['sprites','Sprite workshop','Paint, trace, animate and manage sprite palettes','image'],['creatures','Pokémon & forms','Species designs, evolutions and alternate forms','note'],['story','Story','Arrange story beats, link real scenes and saved prerequisites','link'],['authoring','Game maker','Scenes, flags, NPCs, item maker, music, opening and options','note'],['game','Game data','Trainers, items, encounters, moves and ROM data','grid'],['source','Engine & source','Decomp, CFRU switches, source sprites and music','grid'],['play','Playtest','Run your edited GBA game','move']].map(([id,title,description,svg])=>`<button data-workspace="${id}" type="button" class="${workspace===id?'active':''}">${icon(svg)}<span><b>${title}</b><small>${description}</small></span></button>`).join('')}</div><div class="divider"></div><div class="toolbox-actions"><button id="workspaceProjects" type="button">Projects & backups</button><button id="workspaceNotes" type="button">Map notes</button><button id="workspaceReference" type="button">Trace reference</button></div>`);
  $$('#dialogBody button[data-workspace]').forEach(b=>b.onclick=()=>openWorkspace(b.dataset.workspace));$('#workspaceProjects').onclick=projectMenu;$('#workspaceNotes').onclick=()=>{$('#dialog').close();setPanel('notes');};$('#workspaceReference').onclick=referenceDialog;
}
async function openWorkspace(id){workspaceSwitchPending=true;if(storyTools?.state.active&&id!=='story')storyTools.close();$('#dialog').close();workspace=id;collapsePanel();syncNavigation();try{if(id==='map'){setView('map');return;}if(id==='story')storyTools.open();else if(id==='sprites')await spriteTools.open();else if(id==='creatures')await creatureTools.open();else if(id==='authoring')await authorTools.open();else if(id==='game')await gameTools.open();else if(id==='source')await sourceTools.open();else if(id==='play')await playROMDialog();}catch(e){showError(e);}finally{workspaceSwitchPending=false;syncNavigation();}}
$('#dialog').addEventListener('close',()=>queueMicrotask(()=>{if(disposed)return;if(!$('#dialog').open&&!romPlayer?.active&&!workspaceSwitchPending){workspace=storyTools?.state.active?'story':'map';if(project)syncNavigation();}}));

function createField(){return fieldWorkshop({project:()=>project,map:m,asset,session:()=>romSession,world:()=>world,events:()=>eventsUI,globalHMs:()=>authorTools.open('hmrules'),testState:()=>sceneUI.testState(),tool:()=>activeTool,ensureImage,imageNow,esc,toast,error:showError,modal,close:closeModal,change,refresh,playROM:playROMDialog,mode:t=>{setView('map');activeLayer='details';setTool(t);refresh();}});}

async function playROMDialog(){
 if(!romSession){modal('Open a ROM to playtest','<p>Choose the source GBA ROM for your project. The game runs offline inside the app, with touch controls and separate test saves.</p><button id="choosePlayROM" type="button" class="primary">Choose GBA ROM</button>');$('#choosePlayROM').onclick=()=>{romPurpose='play';pickROM();};return;}
 const bound=project.maps.filter(map=>map.rom&&!map.rom.isCopy&&(map.rom.sourceId===romSession.id||map.rom.generated&&!map.rom.sourceId)),gameChanges=await gameEditCount()+(Object.keys(project.textEdits?.[romSession?.id]||{}).length+(project.regionMaps?.[romSession?.id]?1:0)+(project.travelEdits?.[romSession?.id]?1:0)),compile=bound.length||gameChanges;
 modal('Play the actual GBA game',`<p>${compile?`Compile ${bound.length} linked map${bound.length===1?'':'s'} and run your edited game.`:'Run the opened ROM. Import its maps to include editor changes.'}</p><p>Start or continue a game, or import your emulator’s .sav from the playtester’s Saves menu. HM objects use your real party and badges. Test sessions save separately on this device.</p>${compile?`<label class="check"><input id="playStaticArtwork" type="checkbox" ${bound.some(m=>m.rom?.recoveryRequiresStatic||m.region||m.generator?.version===3)?'checked':''}> Use static artwork on edited maps</label><p class="hint-line">Recommended for generated settlements. It freezes animation on maps sharing the edited tileset.</p>`:''}<p id="playCompileProgress" role="status"></p>`,async()=>{busy(true,'Preparing game…');try{await persist();const result=compile?await buildRom(project,romSession.reader,{sourceId:romSession.id,renderMap:renderForRom,rasterTimeline:renderNativeOpening,wallStyles:world.walls(),staticArtwork:$('#playStaticArtwork').checked,gateRedrawSpecial:discoverGateRedraw(romSession.reader,{sourceSha256:romSession.id})?.index??null,progress:t=>{if($('#playCompileProgress'))$('#playCompileProgress').textContent=t;}}):{bytes:romSession.reader.bytes.slice(),reports:[],warnings:[]};if(compile){const check=await new GbaMaps(result.bytes).discover();for(const r of result.reports)if(!check.byKey(r.key))throw Error('A compiled map did not reopen correctly.');}await launchCompiledPlay(result);return false;}finally{busy(false);}},compile?'Compile & play':'Play ROM');
}
async function launchCompiledPlay(result){
 const map=m(),report=result.reports.find(r=>r.mapId===map.id);let target=null;
 if(report){const candidates=[];for(let y=0;y<map.height;y++)for(let x=0;x<map.width;x++){const rule=movementAt(map,x,y);if(rule.collision||waterAt(map,x,y)||ledgeAt(map,x,y)||map.markers.some(n=>n.x===x&&n.y===y)||project.links.some(l=>l.runtime&&[l.from,l.to].some(e=>e.mapId===map.id&&e.x===x&&e.y===y)))continue;candidates.push({x,y});}const p=world.state.play?.mapId===map.id?world.state.play:{x:map.width/2,y:map.height/2};candidates.sort((a,b)=>Math.abs(a.x-p.x)+Math.abs(a.y-p.y)-Math.abs(b.x-p.x)-Math.abs(b.y-p.y));if(candidates.length){const[bank,index]=report.key.split('.').map(Number);target={bank,index,...candidates[0],name:map.name};}}
 if(!romPlayer)romPlayer=createROMPlayer({db:()=>db,esc,error:showError,save:saveBlob,afterClose:()=>refresh()});
 if(world.state.play)world.stopPlay();$('#dialog').close();setPanel(activePanel,false);await romPlayer.launch({bytes:result.bytes,sourceId:romSession.id,projectId:project.id,title:report?.name||romSession.reader.filename,target});
}

async function hydrateROMInfo(){let changed=hydrateNativeEvents(project,romSession.reader,romSession.id);const refreshed=new Set();for(const map of project.maps){if(map.rom?.sourceId!==romSession.id||map.rom.generated)continue;const source=romSession.reader.byKey(map.rom.key);if(source?.address!==map.rom.headerAddress)continue;if(await exposeNativeLayers(project,map,romSession.reader,encodeRGBA))changed=true;const atlas=romSession.reader.atlas(source);for(const a of project.assets.filter(a=>a.rom?.sourceId===romSession.id&&a.rom.primary===source.layout.primary&&a.rom.secondary===source.layout.secondary)){if(refreshed.has(a.id)||a.rom.rendererVersion===3)continue;const pixels=Number.isInteger(a.rom.layer)?atlas.layers[a.rom.layer]:atlas.pixels;if(!pixels)continue;a.data=encodeRGBA({width:atlas.width,height:atlas.height,pixels});a.width=atlas.width;a.height=atlas.height;a.rom.rendererVersion=3;a.rom.metatileLayers=atlas.metatileLayers||2;imageCache.delete(a.id);imagePending.delete(a.id);badImages.delete(a.id);refreshed.add(a.id);changed=true;}if(!map.rom.attributes||map.rom.rendererVersion!==3){map.rom.attributes=Array.from(atlas.attrs);map.rom.metatileLayers=atlas.metatileLayers||2;map.rom.rendererVersion=3;changed=true;}if(map.rom.dark===undefined){map.rom.dark=romSession.reader.u8(source.address+21)===1;changed=true;}}if(changed){markDirty();await loadMapImages(m());requestDraw();}}

function choosePrefab(p){if(!p)return;change(()=>library.attach(project,'prefabs',p));const a=asset(p.assetId);stampPrefab=p;stampBrush={assetId:p.assetId,sx:p.sx||0,sy:p.sy||0,cols:(p.sw||a.width)/(a.tileSize||16),rows:(p.sh||a.height)/(a.tileSize||16),tileSize:a.tileSize||16};activeLayer='objects';setView('map');setTool('stamp');selectedPrefab=p;brush=clone(stampBrush);refresh();collapsePanel();toast('Tap the map to place '+p.name+'.');}
function createDoors(){return doorWorkshop({project:()=>project,map:m,session:()=>romSession,save:(...args)=>saveBlob(...args),smart:()=>smart,asset,library,esc,toast,error:showError,modal,close:closeModal,change,refresh,loadMap:id=>switchMap(id),mode:t=>{setView('map');setTool(t);refresh();}});}

async function gameEditCount(){const a=readAuthoring(project),nativeChanges=(project.hmRules?1:0)+(project.doorAnimations?.[romSession?.id]?1:0)+(project.cryEdits?.[romSession?.id]?1:0)+(project.tilesetAnimations?.[romSession?.id]?1:0),authored=nativeChanges+Object.keys(a.presentation?.texts||{}).length+a.items.filter(i=>i.enabled!==false&&i.install==='replace').length;if(!Object.keys(project.romEdits||{}).length)return authored;return authored+editCount(editsFor(project,(await gameContext(romSession.reader)).hash));}
function createGame(){return gameWorkshop({abilities:()=>abilityTools,items:()=>itemTools,project:()=>project,map:m,session:()=>romSession,esc,toast,error:showError,modal,close:closeModal,change,refresh,events:()=>eventsUI,doors:()=>doors,sprites:()=>spriteTools,creatures:()=>creatureTools,authoring:()=>authorTools,exportROM:exportRomDialog,check:checkProjectDialog,pickROM:purpose=>{romPurpose=purpose;pickROM();}});}
function createSprites(){return spriteWorkshop({readShelf:()=>db?libraryGet('sprite-palettes'):null,writeShelf:libraryPut,creatures:()=>creatureTools,asset,ensureImage,saveProject:fn=>{fn();markDirty();},project:()=>project,session:()=>romSession,esc,toast,error:showError,modal,change,refresh,save:saveBlob,pickROM:purpose=>{romPurpose=purpose;pickROM();}});}
function checkProjectDialog(){try{validateProject(structuredClone(project),allAssets());const audit=releaseAudit(project,{sourceHash:romSession?.id}),unbound=project.maps.filter(m=>!m.rom),portals=project.links.filter(l=>l.runtime),events=project.maps.reduce((n,m)=>n+m.markers.filter(n=>n.runtime).length,0);modal('Project check',`<p class="callout"><b>Project structure passed.</b><br>${project.maps.length} maps · ${portals.length} playable portals · ${events} authored events.</p>${unbound.length?`<p>${unbound.length} planning maps have no ROM slot. Assign them in Map settings if you want them in the game.</p>`:''}${audit.findings.map(f=>`<p class="${f.severity==='error'?'needs-attention':''}"><b>${esc(f.severity==='error'?'Needs attention':'Check')}</b>: ${esc(f.message)}</p>`).join('')}<p>Compile & review checks native graphics capacity, event references, map bounds, jump landings and verified game tables. Play edited ROM tests the actual game.</p><button id="checkCompile" type="button" class="primary">Compile & review</button>`);$('#checkCompile').onclick=exportRomDialog;}catch(e){modal('Project needs attention',`<p>${esc(e.message)}</p>`);}}

function applyPatchDialog(){if(!romSession){romPurpose='patch';pickROM();return;}modal('Apply a BPS / UPS patch',`<p>Source: <b>${esc(romSession.reader.filename)}</b></p><label>BPS / UPS patch<input id="bpsFile" type="file" accept=".bps,.ups,application/octet-stream"></label><p>The patch must match this exact original ROM. The result is saved as a separate GBA file.</p>`,async()=>{const file=$('#bpsFile').files?.[0];if(!file)throw Error('Choose a .bps or .ups patch first.');if(file.size>36*1024*1024)throw Error('Choose a patch under 36 MB.');const patch=new Uint8Array(await file.arrayBuffer()),patched=(String.fromCharCode(...patch.subarray(0,4))==='UPS1'?applyUPS:applyBPS)(romSession.reader.bytes,patch);readyFile(new Blob([patched.bytes],{type:'application/octet-stream'}),safeName(file.name.replace(/\.(bps|ups)$/i,''))+'.gba');return false;},'Check & save patched ROM');}

function createCreatures(){return creatureWorkshop({abilities:()=>abilityTools,map:m,mode:t=>{setView('map');setTool(t);refresh();},close:closeModal,project:()=>project,session:()=>romSession,esc,toast,error:showError,modal,change,refresh,save:saveBlob,sprites:()=>spriteTools,pickROM:purpose=>{romPurpose=purpose;pickROM();}});}

window.mapStudioTrimMemory=()=>{cancelImageJobs();imageCache.protect([]);imageCache.clear();tileChunks.clear();mapPreviews.clear();musicTools?.stop();if(project&&!document.hidden){protectMapImages();requestDraw();}};

window.mapStudioSuspend=()=>{musicTools?.stop();if(pointers.size)cancelGesture();if(dirty)persist().catch(showError);cancelImageJobs();mapPreviews.clear();tileChunks.clear();imageCache.protect([]);imageCache.trim();};
