function disposeEditor(){disposed=true;clearTimeout(saveTimer);clearTimeout(pointerTimer);cancelAnimationFrame(renderFrame);cancelImageJobs();imageCache.clear();tileChunks.clear();mapPreviews.clear();musicTools?.stop();projectStore?.close();}
window.addEventListener("unload",disposeEditor);

window.mapStudioHealth=()=>({version:'4.66.0',at:Date.now(),workspace,view,tool:activeTool,dialogOpen:$('#dialog').open,appInert:$('#app').hasAttribute('inert'),appHasClickHandler:typeof $('#app').onclick==='function',dialogGeneration,pointers:pointers.size,savePending:!!saveInFlight,maps:project?.maps.length||0,images:imageCache.stats(),recentActions,recentErrors});
window.mapStudioRecover=()=>{noteAction('recovery','keep-project-open');dialogGeneration++;if(pointers.size)cancelGesture();const d=$('#dialog');if(d.open)d.close();$('#app').onclick=null;$('#app').inert=false;$('#app').removeAttribute('inert');workspaceSwitchPending=false;workspace='map';if(project){setView('map');syncNavigation();requestDraw();}return true;};

async function makeNativeTerrain(){
 if(!romSession||m().rom?.sourceId!==romSession.id)throw Error('Open the original ROM for this imported map first.');
 const native=romSession.reader.byKey(m().rom.key);if(!native)throw Error('Choose an imported outdoor map.');
 const profiles=await(await fetch('assets/kanto-path-profiles.json')).json(),pack=nativeTerrainPack(romSession.reader,native,romSession.id,profiles),newAssets=pack.assets.filter(a=>!project.assets.some(old=>old.id===a.id)),newStyles=pack.terrains.filter(t=>!project.terrainSets?.some(old=>old.id===t.id));
 if(project.assets.length+newAssets.length>512||(project.terrainSets?.length||0)+newStyles.length>256)throw Error('This project has reached its artwork or brush limit.');
 change(()=>{project.assets.push(...newAssets);project.terrainSets??=[];project.terrainSets.push(...newStyles);});await loadMapImages(m());return pack.terrains.map(t=>t.id);
}

async function rememberROMExport(result){const current=project,session=romSession;const record=await createROMRoundTrip(result.bytes,session.reader.bytes,{sourceId:session.id,reports:result.reports,previous:current.romRoundTrip});if(project!==current||romSession!==session)throw Error('The project or ROM changed during export. Compile again from the current project.');project.romRoundTrip=record;markDirty();await persist();}
function recoverExportSource(reader,id,previousSession){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;const current=project;busy(true,'Checking matching export project…');try{if(file.size>90*1024*1024)throw Error('Choose a matching project JSON under 90 MB.');const saved=JSON.parse(await file.text()),record=saved.romRoundTrip;if(!record)throw Error('Choose the matching editable project saved with this exported ROM. Your current edits have not changed.');const restored=await restoreROMProjectSidecar(saved,reader.bytes);if(!current.maps.some(m=>m.rom?.sourceId===restored.sourceId))throw Error('This export snapshot belongs to another project source. Your current edits have not changed.');if(project!==current)throw Error('The active project changed. Reopen source recovery.');project.romRoundTrip=structuredClone(record);markDirty();await persist();await reviewROMRefresh(reader,id,previousSession);}catch(e){showError(e);}finally{busy(false);}};input.click();}

async function rememberArtwork(c,name,origin={}){
 const target=project,data=c.toDataURL('image/png'),existing=project.assets.find(a=>a.data===data);if(existing)return existing.id;
 if(project.assets.length>=512)throw Error('This project has reached its imported artwork limit.');
 const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(data)),hash=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join(''),id='pieces-'+hash.slice(0,32),pack=packInfo(origin,asset);
 if(project!==target)throw Error('The project changed before the artwork was ready.');const duplicate=project.assets.find(a=>a.data===data);if(duplicate)return duplicate.id;
 change(()=>{project.assets.push({id,name,width:c.width,height:c.height,tileSize:16,data,category:'Assembled object tiles',packId:pack.id,packName:pack.name});});await ensureImage(id);return id;
}
function choosePaintTile(next,label,layer=activeLayer){selectedPrefab=null;brush={...next};tileBrush=clone(brush);activeLayer=layer;setTool('brush');tileLibraryMode='source';refresh();toast('Picked '+label+'.');}
async function openObjectPieces(p){return assembledPieces({asset,ensureImage,drawObject,esc,modal,toast,error:showError,remember:rememberArtwork,selectTile:choosePaintTile,close:()=>$('#dialog').close(),collapse:collapsePanel,prefab:choosePrefab,edit:p=>smart.extract(p).catch(showError)})(p);}
async function pickVisibleTile(t,screen){
 const map=m(),mapId=map.id,w=worldPoint(screen),px=clamp(Math.floor(w.x-t.x*16),0,15),py=clamp(Math.floor(w.y-t.y*16),0,15),choices=[];
 await loadMapImages(map);if(m().id!==mapId)return;
 function candidate(label,layer,draw,tile=null){const c=document.createElement('canvas');c.width=c.height=16;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;draw(ctx);if(ctx.getImageData(px,py,1,1).data[3]<16)return;choices.push({label,layer,canvas:c,tile});}
 const grid=layer=>{if(!visible[layer])return;const tile=getTile(map,layer,t.x,t.y);if(!tile)return;const im=imageNow(tile.a);if(im)candidate(layer[0].toUpperCase()+layer.slice(1),layer,c=>c.drawImage(im,tile.sx,tile.sy,tile.size,tile.size,0,0,16,16),tile);};
 grid('overhead');
 if(visible.objects){
  candidate('Gate artwork','objects',c=>{c.translate(-t.x*16,-t.y*16);drawGates(c,map);});candidate('Wall artwork','objects',c=>{c.translate(-t.x*16,-t.y*16);drawWalls(c,map);});
  candidate('Field object artwork','objects',c=>{c.translate(-t.x*16,-t.y*16);fieldTools?.draw(c,map);});
  for(const o of objectDrawOrder(map).reverse())if(t.x+1>o.x&&t.y+1>o.y&&t.x<o.x+o.w&&t.y<o.y+o.h&&o.opacity!==0)candidate(o.name||'Stamped object','objects',c=>drawObject(c,{...o,x:o.x-t.x,y:o.y-t.y}));
 }
 grid('objects');grid('details');grid('ground');
 if(!choices.length){toast('No visible artwork at this pixel.');return;}
 const apply=async choice=>{if(m().id!==mapId)return;const tile=choice.tile;if(tile)choosePaintTile({assetId:tile.a,sx:tile.sx,sy:tile.sy,cols:1,rows:1,tileSize:tile.size,...(tile.movementMode?{movementMode:tile.movementMode}:{}),...(tile.movementBehavior!==undefined?{movementBehavior:tile.movementBehavior}:{})},choice.label,choice.layer);else{const id=await rememberArtwork(choice.canvas,choice.label+' · picked tile');choosePaintTile({assetId:id,sx:0,sy:0,cols:1,rows:1,tileSize:16},choice.label,choice.layer);}$('#dialog').close();collapsePanel();};
 if(choices.length===1){await apply(choices[0]);return;}
 modal('Pick visible artwork',`<p>Several layers meet here. The top visible piece is first. Choose the artwork you meant; transparent pixels are skipped.</p><div class="pick-choices">${choices.map((c,i)=>`<button type="button" data-pick-choice="${i}"><img src="${c.canvas.toDataURL('image/png')}" alt=""><span>${esc(c.label)}${i===0?' · top visible':''}</span></button>`).join('')}</div>`);
 $$('[data-pick-choice]').forEach(b=>b.onclick=()=>apply(choices[+b.dataset.pickChoice]).catch(showError));
}
